text:
{
  "title": "政治資金パーティー開催禁止法案",
  "lead": {
    "es": "政治《せいじ》のお金《かね》を集《あつ》めるためのパーティーを、だれも開《ひら》いてはいけないと定《さだ》めようとした法律案《ほうりつあん》です。",
    "hs": "政治資金パーティー（参加費を集めて政治活動に使う催《もよお》し）の開催《かいさい》を禁止しようとした法律案です。",
    "std": "政治資金パーティーの開催を禁止し、違反した者への罰則を定めようとした法律案。",
    "univ": "政治資金パーティーをめぐる現状等に鑑み、政治資金パーティーの開催の禁止について定めようとした法律案。"
  },
  "facts": [
    {
      "es": "「政治資金《せいじしきん》パーティー」とは、お金《かね》（参加費《さんかひ》）をとって開《ひら》く集《あつ》まりで、かかったお金《かね》を引《ひ》いた残《のこ》りを政治《せいじ》の活動《かつどう》に使《つか》うものとしていました。オンラインで参加《さんか》できるものもふくみます。",
      "hs": "「政治資金パーティー」を、対価（参加費）を取って行う催《もよお》しで、収入から経費を引いた残りを政治活動に使うものと定義していました。映像や音声で参加できるものも含《ふく》むとしていました。",
      "std": "政治資金パーティーを、対価を徴収して行う催物（映像・音声の送受信で参加できるものを含む）で、収入から経費を差し引いた残額を政治活動に支出するものと定義していた。",
      "univ": "「政治資金パーティー」とは、対価を徴収して行われる催物（映像又は音声の送受信により参加することができるものを含む。）で、当該催物の対価に係る収入の金額から経費の金額を差し引いた残額を当該催物を開催した者又はその者以外の者の政治活動に関し支出をすることとされているものをいうとしていた。"
    },
    {
      "es": "だれも、政治資金《せいじしきん》パーティーを開《ひら》いてはいけないとしていました。",
      "hs": "何人も（だれであっても）、政治資金パーティーを開催《かいさい》してはならないとしていました。",
      "std": "何人も政治資金パーティーを開催してはならないとしていた。",
      "univ": "何人も、政治資金パーティーを開催してはならないものとするとしていた。"
    },
    {
      "es": "この法律《ほうりつ》を使《つか》うときは、集《あつ》まる自由《じゆう》や政治《せいじ》の活動《かつどう》の自由《じゆう》など、憲法《けんぽう》が守《まも》る自由《じゆう》と権利《けんり》をおかさないように気《き》をつけるとしていました。",
      "hs": "法律の適用にあたっては、集会の自由や政治活動の自由など、日本国憲法が保障する国民の自由と権利を不当に侵害《しんがい》しないよう留意するとしていました。",
      "std": "適用に当たっては、集会の自由、政治活動の自由など憲法が保障する国民の自由と権利を不当に侵害しないよう留意しなければならないとしていた。",
      "univ": "この法律の適用に当たっては、集会の自由及び政治活動の自由その他の日本国憲法の保障する国民の自由と権利を不当に侵害しないように留意しなければならないものとするとしていた。"
    },
    {
      "es": "きまりをやぶってパーティーを開《ひら》いた人《ひと》は、1年《ねん》以下《いか》の拘禁刑《こうきんけい》（刑務所《けいむしょ》に入《い》れられる罰《ばつ》）か50万円《まんえん》以下《いか》の罰金《ばっきん》、またはその両方《りょうほう》とするとしていました。選挙《せんきょ》に関《かか》わる権利《けんり》を止《と》めるきまりも置《お》くとしていました。",
      "hs": "違反《いはん》して開催《かいさい》した人は、1年以下の拘禁刑《こうきんけい》か50万円以下の罰金《ばっきん》、またはその両方とし、公民権停止（選挙権などを一定期間失うこと）の規定も設けるとしていました。",
      "std": "違反して開催した者は1年以下の拘禁刑もしくは50万円以下の罰金、またはその併科とし、公民権停止の規定も設けるとしていた。",
      "univ": "第3に違反して政治資金パーティーを開催した者は、1年以下の拘禁刑若しくは50万円以下の罰金に処し、又はこれを併科するものとするとともに、この罪を犯した者に係る公民権停止の規定を設けるとしていた。"
    },
    {
      "es": "成立《せいりつ》していれば、令和《れいわ》8年《ねん》1月《がつ》1日《ついたち》から使《つか》われ始《はじ》める内容《ないよう》でした。",
      "hs": "成立していれば、令和8年1月1日から施行《しこう》する内容でした（寄附《きふ》金｜控除《こうじょ》の対象の拡大などの検討の規定は公布の日から）。",
      "std": "成立していれば、令和8年1月1日から施行する内容だった。ただし、寄附金控除の特例の対象となる公職の範囲の拡大等の検討に関する規定は公布の日から施行するとしていた。",
      "univ": "成立していれば、令和8年1月1日から施行する内容だった。ただし、政治活動に関する寄附をした場合の寄附金控除の特例の対象となる公職の範囲の拡大等の検討に関する規定は、公布の日から施行するとしていた。"
    }
  ]
}
